import{_ as e,c as a,o as n,V as s,am as t}from"./chunks/framework.GYYi-SO7.js";const m=JSON.parse('{"title":"Architecture overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/introduction.md","filePath":"architecture/introduction.md"}'),o={name:"architecture/introduction.md"},i=s('<h1 id="architecture-overview" tabindex="-1">Architecture overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture overview&quot;">​</a></h1><p>knowledge is built around three pieces that each do one job :</p><ul><li><strong><a href="/knowledge/architecture/ingestion.html">Ingestion job</a></strong>: builds and updates the knowledge base by collecting and processing the source data.</li><li><strong><a href="/knowledge/architecture/api.html">API</a></strong>: exposes the knowledge base through a API</li><li><strong><a href="/knowledge/architecture/mcp.html">MCP server</a></strong>: makes the knowledge available to coding agents through the Model Context Protocol (MCP).</li></ul><p><img src="'+t+`" alt="full architecture"></p><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><p>The ingestion job and the API are two independent services, built into two images and deployed apart. They share no code — not a configuration module, not a utility package. What they do share is the Qdrant collections they agree on: the job writes them (<code>ingestion/clients/vectordb.py</code>), the API reads them (<code>api/clients/vectordb.py</code>), and the end-to-end suite runs both against one Qdrant so a drift between the two fails a test.</p><p>Each service has the same shape: general things at the root, and folders for the rest.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>api/                          ingestion/</span></span>
<span class="line"><span>├── bin.py    entry point     ├── bin.py    entry point</span></span>
<span class="line"><span>├── main.py   the app         ├── main.py   the pipeline</span></span>
<span class="line"><span>├── config.py                 ├── config.py</span></span>
<span class="line"><span>├── logger.py                 ├── logger.py</span></span>
<span class="line"><span>├── routes.py                 ├── chunkers/    one per file type</span></span>
<span class="line"><span>├── schemas.py                │   ├── line_locator.py</span></span>
<span class="line"><span>├── services/  what it does   │   ├── markdown.py, javascript.py, …</span></span>
<span class="line"><span>│   ├── retrieval.py          ├── pipeline/    what the job does</span></span>
<span class="line"><span>│   └── security.py           │   ├── workspace_clone.py   fills the workspace</span></span>
<span class="line"><span>└── clients/   what it talks  │   ├── workspace_scanner.py files git tracks</span></span>
<span class="line"><span>    ├── llm.py     to         │   ├── change_detection.py  digests, what moved</span></span>
<span class="line"><span>    ├── embeddings.py         │   └── commit_history.py    commit history</span></span>
<span class="line"><span>    └── vectordb.py           └── clients/     what it talks to</span></span>
<span class="line"><span>                                  ├── embeddings.py</span></span>
<span class="line"><span>                                  └── vectordb.py</span></span></code></pre></div><p><code>services/</code> holds what a service <em>does</em>, <code>clients/</code> what it talks to, and <code>pipeline/</code> the steps of one ingestion run.</p><p>Run them with <code>python -m api.bin</code> and <code>python -m ingestion.bin</code>.</p>`,10),p=[i];function r(c,l,h,d,u,g){return n(),a("div",null,p)}const _=e(o,[["render",r]]);export{m as __pageData,_ as default};
